// ═══ FALSE SHARING: two counters on same cache line ═══
class Counters {
    volatile long counter1;  // 8 bytes, offset 0
    volatile long counter2;  // 8 bytes, offset 8
    // Both fit in ONE 64-byte cache line!
}
// Thread-1: increments counter1 → invalidates ENTIRE cache line on Core-2!
// Thread-2: increments counter2 → invalidates ENTIRE cache line on Core-1!
// Constant ping-pong! Each increment: ~100ns instead of ~5ns!

// ═══ FIX 1: manual padding ═══
class PaddedCounters {
    volatile long counter1;
    long p1, p2, p3, p4, p5, p6, p7;  // 7 × 8 = 56 bytes padding!
    volatile long counter2;
    // counter1 and counter2 are now on DIFFERENT cache lines!
    // No false sharing! Each increment: ~5ns!
}

// ═══ FIX 2: @Contended annotation (Java 8+) ═══
// import jdk.internal.vm.annotation.Contended;
// class ContendedCounters {
//     @Contended volatile long counter1;  // auto-padded!
//     @Contended volatile long counter2;  // auto-padded!
// }
// Requires: -XX:-RestrictContended JVM flag (or internal module access)

// ═══ LongAdder: uses @Contended internally! ═══
// LongAdder.Cell class:
// @Contended static final class Cell {
//     volatile long value;  // padded to own cache line!
// }
// Each thread writes to its own Cell → different cache lines → no false sharing!
// This is WHY LongAdder is 10x faster than AtomicLong under contention!

// ═══ CACHE LINE SIZE ═══
// Most modern CPUs: 64 bytes
// Some server CPUs: 128 bytes (prefetch pairs of 64-byte lines)
// Objects in Java: 12-byte header + fields → may share cache line with adjacent object!
