// ─── File: src/test/java/com/bank/cache/FalseSharingTest.java ───
package com.bank.cache;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class FalseSharingTest {

    // ═══ FALSE SHARING: counters on same cache line ═══
    static class SharedLine {
        volatile long counter1;
        volatile long counter2;
    }

    // ═══ PADDED: counters on different cache lines ═══
    static class PaddedLine {
        volatile long counter1;
        long p1, p2, p3, p4, p5, p6, p7;  // 56 bytes padding!
        volatile long counter2;
    }

    @Test
    void falseSharingBenchmark() throws InterruptedException {
        int iterations = 10_000_000;

        // FALSE SHARING (slow):
        SharedLine shared = new SharedLine();
        long sharedTime = benchmark(shared, iterations, true);

        // PADDED (fast):
        PaddedLine padded = new PaddedLine();
        long paddedTime = benchmark(padded, iterations, false);

        System.out.println("False sharing: " + sharedTime + "ms");
        System.out.println("Padded: " + paddedTime + "ms");
        System.out.println("Speedup: " + (sharedTime / Math.max(paddedTime, 1)) + "x");
        // Padded is typically 2-5x faster!
    }

    long benchmark(Object counters, int iterations, boolean shared) throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(2);
        long start = System.currentTimeMillis();

        if (shared) {
            SharedLine s = (SharedLine) counters;
            new Thread(() -> { for (int i = 0; i < iterations; i++) s.counter1++; latch.countDown(); }).start();
            new Thread(() -> { for (int i = 0; i < iterations; i++) s.counter2++; latch.countDown(); }).start();
        } else {
            PaddedLine p = (PaddedLine) counters;
            new Thread(() -> { for (int i = 0; i < iterations; i++) p.counter1++; latch.countDown(); }).start();
            new Thread(() -> { for (int i = 0; i < iterations; i++) p.counter2++; latch.countDown(); }).start();
        }

        latch.await();
        return System.currentTimeMillis() - start;
    }

    // ═══ LongAdder: no false sharing (@Contended cells) ═══
    @Test
    void longAdder_noFalseSharing() throws InterruptedException {
        java.util.concurrent.atomic.LongAdder adder = new java.util.concurrent.atomic.LongAdder();
        int threads = 4;
        int iterations = 10_000_000;
        CountDownLatch latch = new CountDownLatch(threads);

        long start = System.currentTimeMillis();
        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < iterations; i++) adder.increment();
                latch.countDown();
            }).start();
        }
        latch.await();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(adder.sum()).isEqualTo((long) threads * iterations);
        System.out.println("LongAdder: " + elapsed + "ms for " + (threads * iterations) + " ops");
    }
}
